import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = Integer.parseInt(in.nextLine().trim());

        String engYuqori = "";
        int engKatta = -1;
        for (int i = 0; i < n; i++) {
            String[] maydon = in.nextLine().trim().split(",");
            int ball = Integer.parseInt(maydon[1]);
            if (ball >= engKatta) {
                engKatta = ball;
                engYuqori = maydon[0];
            }
        }

        System.out.println(engYuqori);
        System.out.println(engKatta);
    }
}

